from collections import Counter,deque

def transform(grid):
    g=[r[:] for r in grid]; H=len(g); W=len(g[0]); S=5
    cnt=Counter(x for r in g for x in r)
    seed=min((v,k) for k,v in cnt.items() if k!=1)[1]
    wall=max((v,k) for k,v in cnt.items() if k!=1)[1]
    walls={(r,c) for r in range(H) for c in range(W) if g[r][c]==wall}
    wh=[[False]*(W*S) for _ in range(H*S)]
    for r,c in walls:
        for i in range(r*S,(r+1)*S):
            for j in range(c*S,(c+1)*S):wh[i][j]=True
    # Connect centers of diagonal wall cells with a thick digital line.
    for r,c in walls:
        for dr,dc in ((1,1),(1,-1)):
            if (r+dr,c+dc) in walls:
                y0,x0=r*S+S//2,c*S+S//2; y1,x1=(r+dr)*S+S//2,(c+dc)*S+S//2
                for k in range(S+1):
                    y=round(y0+(y1-y0)*k/S); x=round(x0+(x1-x0)*k/S)
                    for dy in (-1,0,1):
                        for dx in (-1,0,1): wh[y+dy][x+dx]=True
    sr,sc=next((r,c) for r in range(H) for c in range(W) if g[r][c]==seed)
    start=(sr*S+S//2,sc*S+S//2); q=deque([start]); seen={start}
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H*S and 0<=cc<W*S and not wh[rr][cc] and (rr,cc) not in seen:
                seen.add((rr,cc));q.append((rr,cc))
    for r in range(H):
        for c in range(W):
            if g[r][c]==1 and (r*S+S//2,c*S+S//2) in seen:g[r][c]=seed
    return g
